 "content": "def transform(grid):
    """Mark the extra suffix of a repeated horizontal pattern in color 1."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    rows = [[c for c, v in enumerate(row) if v == 8] for row in grid]
    for r, cols in enumerate(rows):
        if not cols:
            continue
        last = max(cols)
        for rr, other in enumerate(rows):
            if rr == r or len(other) <= len(cols):
                continue
            # A repeated shape with a strictly longer 8-pattern is a template
            # when it contains every 8 of this row and adds a solid suffix.
            if set(cols).issubset(other) and all(c in other for c in range(last + 1, w)):
                extras = [c for c in other if c not in set(cols)]
                if extras and extras == list(range(last + 1, w)):
                    for c in extras:
                        out[r][c] = 1
                break
    return out
